// The RPC client for .NET: one WebSocket carries any number of concurrent calls of the four kinds (unary, server
// streaming, client streaming, bidirectional), with deadlines, cancellation and flow control in both directions.
//
//   await using var rpc = await RpcClient.ConnectAsync("ws://localhost:8080/rpc");
//   var calc = new CalcClient(rpc);                                   // generated by `rpcc --cs`
//   double sum = await calc.AddAsync(40, 2);
//   await foreach (var tick in calc.CountAsync(1, 5)) Console.WriteLine(tick.Label);
//
// When the connection is lost every call fails with RpcException(Code.Unavailable); connect again to continue.
using System.Net.WebSockets;
using System.Threading.Channels;
using Bufs;
using Rpc.Wire;

namespace Librpc;

/// <summary>The status codes of a call (gRPC's numbers, on the wire).</summary>
public enum Code : ushort
{
    Ok = 0, Cancelled = 1, Unknown = 2, InvalidArgument = 3, DeadlineExceeded = 4, NotFound = 5, AlreadyExists = 6,
    PermissionDenied = 7, ResourceExhausted = 8, FailedPrecondition = 9, Aborted = 10, OutOfRange = 11, Unimplemented = 12,
    Internal = 13, Unavailable = 14, DataLoss = 15, Unauthenticated = 16,
}

public sealed class RpcException : Exception
{
    public RpcException(Code code, string message, uint detail = 0) : base(message.Length == 0 ? code.ToString() : $"{code}: {message}")
    {
        Code = code;
        Detail = detail;
        StatusMessage = message;
    }

    public Code Code { get; }
    /// <summary>Application-defined detail of the status (0 = none).</summary>
    public uint Detail { get; }
    public string StatusMessage { get; }
}

public sealed class ClientOptions
{
    /// <summary>Credentials for a server whose authenticate hook reads the Hello's token.</summary>
    public string? Token { get; set; }
    public string Peer { get; set; } = "librpc-cs/0.1";
    /// <summary>Bytes of stream items the server may send before we have consumed some.</summary>
    public int Window { get; set; } = 1 << 20;
    /// <summary>Largest message we accept.</summary>
    public int MaxMessage { get; set; } = 16 << 20;
    /// <summary>A ping after this much silence, so the server's idle timeout does not close the connection (zero: never).</summary>
    public TimeSpan PingInterval { get; set; } = TimeSpan.FromSeconds(15);
    public TimeSpan ConnectTimeout { get; set; } = TimeSpan.FromSeconds(10);
    /// <summary>Extra handshake headers (Authorization, Cookie, ...).</summary>
    public Dictionary<string, string> Headers { get; } = new();
}

public sealed class CallOptions
{
    /// <summary>The whole call must end within this; the server is told, and the client gives up at the same time.</summary>
    public TimeSpan? Timeout { get; set; }
    public CancellationToken CancellationToken { get; set; }
}

public sealed class RpcClient : IAsyncDisposable
{
    private const string Subprotocol = "librpc.v1";

    private readonly ClientWebSocket _ws;
    private readonly SemaphoreSlim _sendLock = new(1, 1);
    private readonly object _gate = new();
    private readonly Dictionary<uint, Call> _calls = new();
    private readonly CancellationTokenSource _stop = new();
    private readonly ClientOptions _options;
    private Task _reader = Task.CompletedTask;
    private Task _pinger = Task.CompletedTask;
    private uint _nextId = 1;
    private RpcException? _closed;
    private long _window;
    private long _serverMaxMessage;
    private long _sendUnacked;
    private long _consumed;
    private List<TaskCompletionSource> _creditWaiters = new();

    /// <summary>The server's name and this connection's session id, from the Welcome.</summary>
    public string ServerName { get; private set; } = "";
    public ulong SessionId { get; private set; }

    private RpcClient(ClientWebSocket ws, ClientOptions options)
    {
        _ws = ws;
        _options = options;
        _window = options.Window;
    }

    public bool Connected
    {
        get { lock (_gate) return _closed == null && _ws.State == WebSocketState.Open; }
    }

    /// <summary>Connects, says Hello and waits for the Welcome. Throws RpcException.</summary>
    public static async Task<RpcClient> ConnectAsync(string url, ClientOptions? options = null, CancellationToken cancellationToken = default)
    {
        options ??= new ClientOptions();
        var ws = new ClientWebSocket();
        ws.Options.AddSubProtocol(Subprotocol);
        foreach (var (name, value) in options.Headers)
            ws.Options.SetRequestHeader(name, value);
        var client = new RpcClient(ws, options);
        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timeout.CancelAfter(options.ConnectTimeout);
        try
        {
            await ws.ConnectAsync(new Uri(url), timeout.Token).ConfigureAwait(false);
            await client.SendFrameAsync(Envelope.Encode(new EnvelopeInit
            {
                Kind = Kind.Hello,
                Protocol = 1,
                Peer = options.Peer,
                Token = options.Token,
                Window = (ulong)options.Window,
                MaxMessage = (uint)options.MaxMessage,
            }), default, timeout.Token).ConfigureAwait(false);
            var frame = await client.ReceiveAsync(timeout.Token).ConfigureAwait(false);
            var env = Envelope.Decode(frame);
            if (env.Kind == Kind.End)
                throw new RpcException((Code)env.Code, env.Message, env.Detail);
            if (env.Kind != Kind.Welcome)
                throw new RpcException(Code.DataLoss, "expected Welcome");
            client.ServerName = env.Peer;
            client.SessionId = env.Session;
            if (env.Window != 0) client._window = (long)env.Window;
            client._serverMaxMessage = env.MaxMessage;
        }
        catch (RpcException)
        {
            ws.Dispose();
            throw;
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            ws.Dispose();
            throw new RpcException(Code.DeadlineExceeded, "connect timed out");
        }
        catch (Exception e) when (e is WebSocketException or HttpRequestException or InvalidOperationException or IOException)
        {
            ws.Dispose();
            throw new RpcException(Code.Unavailable, e.InnerException?.Message ?? e.Message);
        }
        client._reader = Task.Run(client.ReadLoopAsync);
        if (options.PingInterval > TimeSpan.Zero)
            client._pinger = Task.Run(client.PingLoopAsync);
        return client;
    }

    // ---- calls ------------------------------------------------------------------------------------------------

    /// <summary>A unary call: <paramref name="request"/> is a finished message, <paramref name="decode"/> reads the response.</summary>
    public async Task<T> CallAsync<T>(uint method, byte[] request, Func<ReadOnlyMemory<byte>, T> decode, CallOptions? options = null)
    {
        var call = await BeginAsync(method, request, b => decode(b), null, options, stream: false).ConfigureAwait(false);
        var result = await call.Unary!.Task.ConfigureAwait(false);
        return (T)result!;
    }

    /// <summary>A server-streaming call. Errors surface from the enumeration.</summary>
    public RpcStream<T> Stream<T>(uint method, byte[] request, Func<ReadOnlyMemory<byte>, T> decode, CallOptions? options = null)
        => new RpcStream<T>(this, StartLazy(method, request, b => decode(b), null, options));

    /// <summary>A stream whose method has a trailer (or the answer of a client-streaming call, as <c>Trailer</c>).</summary>
    public RpcStream<T, TTrailer> Stream<T, TTrailer>(uint method, byte[] request, Func<ReadOnlyMemory<byte>, T> decode, CallOptions? options,
        Func<ReadOnlyMemory<byte>, TTrailer> decodeTrailer)
        => new RpcStream<T, TTrailer>(this, StartLazy(method, request, b => decode(b), b => decodeTrailer(b), options));

    private Task<Call> StartLazy(uint method, byte[] request, Func<ReadOnlyMemory<byte>, object?> decode, Func<ReadOnlyMemory<byte>, object?>? decodeTrailer, CallOptions? options)
        => BeginAsync(method, request, decode, decodeTrailer, options, stream: true);

    private async Task<Call> BeginAsync(uint method, byte[] request, Func<ReadOnlyMemory<byte>, object?> decode, Func<ReadOnlyMemory<byte>, object?>? decodeTrailer,
        CallOptions? options, bool stream)
    {
        var call = new Call { Decode = decode, DecodeTrailer = decodeTrailer, IsStream = stream };
        if (stream)
            call.Items = Channel.CreateUnbounded<(object?, int)>(new UnboundedChannelOptions { SingleReader = true, SingleWriter = true });
        else
            call.Unary = new TaskCompletionSource<object?>(TaskCreationOptions.RunContinuationsAsynchronously);
        call.Completed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        lock (_gate)
        {
            if (_closed != null) throw _closed;
            do { call.Id = _nextId++; } while (call.Id == 0 || _calls.ContainsKey(call.Id));
            _calls[call.Id] = call;
        }
        if (_serverMaxMessage != 0 && request.Length + 64 > _serverMaxMessage)
        {
            Finish(call, new RpcException(Code.ResourceExhausted, "request exceeds the server's maximum message size"));
            throw (RpcException)call.Failure!;
        }
        var ct = options?.CancellationToken ?? default;
        if (options?.Timeout is { } timeout)
        {
            call.Deadline = new CancellationTokenSource(timeout);
            call.Deadline.Token.Register(() => CancelCall(call, new RpcException(Code.DeadlineExceeded, "deadline exceeded")));
        }
        if (ct.CanBeCanceled)
            call.Registration = ct.Register(() => CancelCall(call, new RpcException(Code.Cancelled, "cancelled")));
        try
        {
            await SendFrameAsync(Envelope.Encode(new EnvelopeInit
            {
                Id = call.Id,
                Kind = Kind.Call,
                Method = method,
                DeadlineMs = options?.Timeout is { } t ? (uint)Math.Min(t.TotalMilliseconds, uint.MaxValue) : null,
            }), request, CancellationToken.None).ConfigureAwait(false);
        }
        catch (Exception e)
        {
            var failure = e as RpcException ?? new RpcException(Code.Unavailable, e.Message);
            Finish(call, failure);
            throw failure;
        }
        return call;
    }

    internal void CancelCall(Call call, RpcException reason)
    {
        bool known;
        lock (_gate) known = _calls.ContainsKey(call.Id);
        if (!known) return;
        _ = SendFrameAsync(Envelope.Encode(new EnvelopeInit { Id = call.Id, Kind = Kind.Cancel }), default, CancellationToken.None)
            .ContinueWith(t => _ = t.Exception, TaskContinuationOptions.OnlyOnFaulted);
        Finish(call, reason);
    }

    // Sends one item of a client-streaming or bidirectional call, waiting while the server has not read enough.
    internal async Task<bool> SendItemAsync(Call call, ReadOnlyMemory<byte> message, CancellationToken ct)
    {
        int frameBytes = 64 + message.Length;
        if (_serverMaxMessage != 0 && frameBytes > _serverMaxMessage)
            throw new RpcException(Code.ResourceExhausted, "stream item exceeds the server's maximum message size");
        for (;;)
        {
            TaskCompletionSource? wait = null;
            lock (_gate)
            {
                if (_closed != null || call.Done) return false;
                if (_sendUnacked == 0 || _sendUnacked + frameBytes <= _window)
                {
                    _sendUnacked += frameBytes;
                    break;
                }
                wait = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
                _creditWaiters.Add(wait);
            }
            await wait.Task.WaitAsync(ct).ConfigureAwait(false);
        }
        var envelope = Envelope.Encode(new EnvelopeInit { Id = call.Id, Kind = Kind.Data });
        // The server counts the whole frame; what we booked above was a little more than the real size.
        long refund = 64 + message.Length - (envelope.Length + message.Length);
        if (refund > 0) lock (_gate) _sendUnacked = Math.Max(0, _sendUnacked - refund);
        try
        {
            await SendFrameAsync(envelope, message, ct).ConfigureAwait(false);
        }
        catch (Exception e) when (e is not OperationCanceledException)
        {
            return false;
        }
        return true;
    }

    internal Task EndItemsAsync(Call call) =>
        call.Done ? Task.CompletedTask : SendFrameAsync(Envelope.Encode(new EnvelopeInit { Id = call.Id, Kind = Kind.End }), default, CancellationToken.None);

    // The caller consumed (or dropped) stream items of this many frame bytes: credit them once a quarter window has piled up.
    internal void Consumed(int frameBytes)
    {
        long report = 0;
        lock (_gate)
        {
            _consumed += frameBytes;
            if (_consumed >= Math.Max(1, _window / 4))
            {
                report = _consumed;
                _consumed = 0;
            }
        }
        if (report > 0)
            _ = SendFrameAsync(Envelope.Encode(new EnvelopeInit { Kind = Kind.Credit, Credit = (ulong)report }), default, CancellationToken.None)
                .ContinueWith(t => _ = t.Exception, TaskContinuationOptions.OnlyOnFaulted);
    }

    // ---- transport --------------------------------------------------------------------------------------------

    private async Task SendFrameAsync(byte[] envelope, ReadOnlyMemory<byte> body, CancellationToken ct)
    {
        var frame = new byte[envelope.Length + body.Length];
        envelope.CopyTo(frame, 0);
        body.CopyTo(frame.AsMemory(envelope.Length));
        await _sendLock.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            if (_ws.State != WebSocketState.Open) throw new RpcException(Code.Unavailable, "the connection is closed");
            await _ws.SendAsync(frame, WebSocketMessageType.Binary, true, ct).ConfigureAwait(false);
        }
        catch (WebSocketException e)
        {
            throw new RpcException(Code.Unavailable, e.Message);
        }
        finally
        {
            _sendLock.Release();
        }
    }

    private async Task<byte[]> ReceiveAsync(CancellationToken ct)
    {
        var buffer = new byte[16384];
        int length = 0;
        for (;;)
        {
            if (length == buffer.Length) Array.Resize(ref buffer, buffer.Length * 2);
            var result = await _ws.ReceiveAsync(buffer.AsMemory(length), ct).ConfigureAwait(false);
            if (result.MessageType == WebSocketMessageType.Close)
                throw new RpcException(Code.Unavailable, $"connection closed ({(int?)_ws.CloseStatus}) {_ws.CloseStatusDescription}".Trim());
            if (result.MessageType != WebSocketMessageType.Binary)
                throw new RpcException(Code.DataLoss, "text frame from server");
            length += result.Count;
            if (result.EndOfMessage) break;
            if (length > _options.MaxMessage) throw new RpcException(Code.ResourceExhausted, "message from server exceeds the maximum");
        }
        Array.Resize(ref buffer, length);
        return buffer;
    }

    private async Task ReadLoopAsync()
    {
        try
        {
            for (;;)
            {
                var frame = await ReceiveAsync(_stop.Token).ConfigureAwait(false);
                Dispatch(frame);
            }
        }
        catch (Exception e)
        {
            Lost(e as RpcException ?? new RpcException(Code.Unavailable, e is OperationCanceledException ? "client closed" : $"connection lost: {e.Message}"));
        }
    }

    private async Task PingLoopAsync()
    {
        using var timer = new PeriodicTimer(_options.PingInterval);
        try
        {
            while (await timer.WaitForNextTickAsync(_stop.Token).ConfigureAwait(false))
                await SendFrameAsync(Envelope.Encode(new EnvelopeInit { Kind = Kind.Ping }), default, _stop.Token).ConfigureAwait(false);
        }
        catch
        {
            // the reader reports a dead connection
        }
    }

    private void Dispatch(byte[] frame)
    {
        var env = Envelope.Decode(frame);
        int size = Table.MessageSize(frame);
        ReadOnlyMemory<byte> body = size < frame.Length ? frame.AsMemory(size) : default;
        switch (env.Kind)
        {
            case Kind.Data:
            {
                Call? call;
                lock (_gate) _calls.TryGetValue(env.Id, out call);
                if (call?.Items == null || body.IsEmpty)
                {
                    Consumed(frame.Length);  // for a call that is gone: the server still counts these bytes
                    return;
                }
                object? item;
                try { item = call.Decode!(body); }
                catch (Exception) { CancelCall(call, new RpcException(Code.DataLoss, "malformed stream item")); return; }
                call.Items.Writer.TryWrite((item, frame.Length));
                return;
            }
            case Kind.End:
            {
                if (env.Id == 0)
                {
                    Lost(new RpcException((Code)env.Code, env.Message, env.Detail));
                    return;
                }
                Call? call;
                lock (_gate) _calls.TryGetValue(env.Id, out call);
                if (call == null) return;
                if ((Code)env.Code != Code.Ok)
                {
                    Finish(call, new RpcException((Code)env.Code, env.Message, env.Detail));
                    return;
                }
                try
                {
                    if (!body.IsEmpty)
                    {
                        if (call.IsStream)
                            call.Trailer = call.DecodeTrailer?.Invoke(body);
                        else
                            call.Result = call.Decode!(body);
                    }
                    else if (!call.IsStream)
                    {
                        Finish(call, new RpcException(Code.DataLoss, "the server sent no response"));
                        return;
                    }
                }
                catch (Exception e)
                {
                    Finish(call, new RpcException(Code.DataLoss, $"malformed response: {e.Message}"));
                    return;
                }
                Finish(call, null);
                return;
            }
            case Kind.Credit:
            {
                List<TaskCompletionSource> waiting;
                lock (_gate)
                {
                    _sendUnacked = Math.Max(0, _sendUnacked - (long)env.Credit);
                    waiting = _creditWaiters;
                    _creditWaiters = new();
                }
                foreach (var w in waiting) w.TrySetResult();
                return;
            }
            case Kind.Closing:
                lock (_gate) _closed ??= new RpcException(Code.Unavailable, "server is shutting down");
                return;
            default:
                return;
        }
    }

    // A call is over: with a failure, or (null) cleanly.
    internal void Finish(Call call, RpcException? failure)
    {
        List<TaskCompletionSource> waiting;
        lock (_gate)
        {
            if (call.Done) return;
            call.Done = true;
            call.Failure = failure;
            _calls.Remove(call.Id);
            waiting = _creditWaiters;
            _creditWaiters = new();
        }
        call.Registration.Dispose();
        call.Deadline?.Dispose();
        foreach (var w in waiting) w.TrySetResult();  // senders re-check and see the call is over
        if (call.Unary != null)
        {
            if (failure != null) call.Unary.TrySetException(failure);
            else call.Unary.TrySetResult(call.Result);
        }
        call.Items?.Writer.TryComplete(failure);
        if (failure != null) call.Completed!.TrySetException(failure); else call.Completed!.TrySetResult();
    }

    private void Lost(RpcException error)
    {
        List<Call> live;
        lock (_gate)
        {
            _closed ??= error;
            live = _calls.Values.ToList();
        }
        foreach (var call in live) Finish(call, _closed!);
    }

    public async ValueTask DisposeAsync()
    {
        Lost(new RpcException(Code.Unavailable, "client closed"));
        _stop.Cancel();
        try
        {
            if (_ws.State == WebSocketState.Open)
            {
                using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(2));
                await _sendLock.WaitAsync(timeout.Token).ConfigureAwait(false);
                try { await _ws.CloseAsync(WebSocketCloseStatus.NormalClosure, "bye", timeout.Token).ConfigureAwait(false); }
                finally { _sendLock.Release(); }
            }
        }
        catch
        {
            // closing is best effort
        }
        try { await Task.WhenAll(_reader, _pinger).ConfigureAwait(false); } catch { }
        _ws.Dispose();
        _stop.Dispose();
    }

    internal sealed class Call
    {
        public uint Id;
        public Func<ReadOnlyMemory<byte>, object?>? Decode;
        public Func<ReadOnlyMemory<byte>, object?>? DecodeTrailer;
        public bool IsStream;
        public bool Done;
        public RpcException? Failure;
        public object? Result;
        public object? Trailer;
        public TaskCompletionSource<object?>? Unary;
        public Channel<(object? Item, int FrameBytes)>? Items;
        public TaskCompletionSource? Completed;
        public CancellationTokenSource? Deadline;
        public CancellationTokenRegistration Registration;
    }
}

public struct NoTrailer { }

/// <summary>
/// A call that streams: <c>await foreach</c> reads the server's items (a break cancels the call). For client streaming and
/// bidirectional calls, <see cref="SendAsync"/> and <see cref="End"/> send the caller's.
/// </summary>
public class RpcStream<T> : IAsyncEnumerable<T>
{
    private readonly RpcClient _client;
    private readonly Task<RpcClient.Call> _call;

    internal RpcStream(RpcClient client, Task<RpcClient.Call> call)
    {
        _client = client;
        _call = call;
    }

    internal Task<RpcClient.Call> Started => _call;

    /// <summary>Sends one item (a finished message). False: the call is over, stop sending.</summary>
    public async Task<bool> SendAsync(ReadOnlyMemory<byte> message, CancellationToken cancellationToken = default)
    {
        var call = await _call.ConfigureAwait(false);
        return await _client.SendItemAsync(call, message, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Says that no more items will be sent.</summary>
    public async Task EndAsync()
    {
        var call = await _call.ConfigureAwait(false);
        await _client.EndItemsAsync(call).ConfigureAwait(false);
    }

    /// <summary>Completes when the call is over (throws RpcException if it failed).</summary>
    public async Task WaitAsync()
    {
        var call = await _call.ConfigureAwait(false);
        await call.Completed!.Task.ConfigureAwait(false);
    }

    public async void Cancel()
    {
        try
        {
            var call = await _call.ConfigureAwait(false);
            _client.CancelCall(call, new RpcException(Code.Cancelled, "cancelled"));
        }
        catch
        {
            // never started
        }
    }

    internal async Task<object?> TrailerObjectAsync()
    {
        var call = await _call.ConfigureAwait(false);
        return call.Trailer;
    }

    public async IAsyncEnumerator<T> GetAsyncEnumerator(CancellationToken cancellationToken = default)
    {
        var call = await _call.ConfigureAwait(false);
        var reader = call.Items!.Reader;
        try
        {
            while (await reader.WaitToReadAsync(cancellationToken).ConfigureAwait(false))
            {
                while (reader.TryRead(out var entry))
                {
                    _client.Consumed(entry.FrameBytes);
                    yield return (T)entry.Item!;
                }
            }
        }
        finally
        {
            if (!call.Done)  // stopped early: abandon the call
                _client.CancelCall(call, new RpcException(Code.Cancelled, "cancelled"));
        }
    }
}

/// <summary>A stream whose method declares a trailer: after the enumeration ends, <see cref="Trailer"/> holds it.</summary>
public sealed class RpcStream<T, TTrailer> : RpcStream<T>
{
    internal RpcStream(RpcClient client, Task<RpcClient.Call> call) : base(client, call) { }

    /// <summary>The closing message; <c>default</c> until the stream has ended in Ok.</summary>
    public TTrailer? Trailer
    {
        get
        {
            var call = Started.IsCompletedSuccessfully ? Started.Result : null;
            return call?.Trailer is TTrailer t ? t : default;
        }
    }
}

/// <summary>A client-streaming call: <see cref="SendAsync"/> items, then <see cref="FinishAsync"/> for the answer.</summary>
public sealed class RpcUpload<TItem, TResult>
{
    private readonly RpcStream<object, TResult> _stream;
    private readonly Func<TItem, byte[]> _encode;

    public RpcUpload(RpcStream<object, TResult> stream, Func<TItem, byte[]> encode)
    {
        _stream = stream;
        _encode = encode;
    }

    /// <summary>False: the call is already over (the server answered or it was cancelled); call FinishAsync to learn how.</summary>
    public Task<bool> SendAsync(TItem item, CancellationToken cancellationToken = default) => _stream.SendAsync(_encode(item), cancellationToken);

    /// <summary>Says there are no more items, waits for the answer and returns it.</summary>
    public async Task<TResult> FinishAsync()
    {
        await _stream.EndAsync().ConfigureAwait(false);
        await _stream.WaitAsync().ConfigureAwait(false);
        return (TResult)(await _stream.TrailerObjectAsync().ConfigureAwait(false))!;
    }

    public void Cancel() => _stream.Cancel();
}

/// <summary>A bidirectional call: send and end on one side, <c>await foreach</c> on the other (they may run concurrently).</summary>
public sealed class RpcDuplex<TItem, TOut> : IAsyncEnumerable<TOut>
{
    private readonly RpcStream<TOut> _stream;
    private readonly Func<TItem, byte[]> _encode;

    public RpcDuplex(RpcStream<TOut> stream, Func<TItem, byte[]> encode)
    {
        _stream = stream;
        _encode = encode;
    }

    public Task<bool> SendAsync(TItem item, CancellationToken cancellationToken = default) => _stream.SendAsync(_encode(item), cancellationToken);

    /// <summary>No more items from this side; the server's stream goes on until it ends.</summary>
    public Task EndAsync() => _stream.EndAsync();

    public void Cancel() => _stream.Cancel();

    public IAsyncEnumerator<TOut> GetAsyncEnumerator(CancellationToken cancellationToken = default) => _stream.GetAsyncEnumerator(cancellationToken);
}
